        turnsLeft: duration,
        maxTurns: duration,
        potency: 1,
        stacks: 1,
        sourceId: itemId,
        sourceKind: 'scroll',
        sourceKey: String(state?.identity || ''),
      });
      ctx.io.emit('scroll:fumbled', { actor, itemId, identity: String(state?.identity || ''), effectKey: 'confused', duration });
