const ITEM_HOOK_MAP = {
  onUse:       'on_use',
  onDrink:     'on_drink',
  onThrow:     'on_throw',
  onDip:       'on_dip',
  beforeUse:   'before_use',
  afterUse:    'after_use',
  beforeDrink: 'before_drink',
